'use client';

import { useEffect, useRef, useState } from 'react';

import { ChevronRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

import { ConversationPane, type Typing } from './conversation-pane';
import {
  COMMENTS,
  EVENTS,
  LATER_REPLIES,
  NOW,
  SUBTASKS,
  TASK,
  type TaskComment,
} from './data';
import { RollingCount } from './motion-parts';
import { SubtaskPanel } from './subtask-panel';
import {
  PeopleStack,
  ProgressRing,
  STATUS_NAME,
  StatusGlyph,
} from './work-glyphs';
import {
  addedSubtask,
  doneCountOf,
  dueLabelOf,
  nextSeq,
  personOf,
  postedComment,
  toggledSubtask,
  withComment,
  type WorkState,
} from './work-model';

type Pane = 'task' | 'conversation';

const TYPING_STARTS_AFTER_MS = 900;

const TYPING_LASTS_MS = 2600;

const FIRST_STATE: WorkState = {
  subtasks: SUBTASKS,
  comments: COMMENTS,
  events: EVENTS,
};

function isPane(value: unknown): value is Pane {
  const isTask = value === 'task';
  const isConversation = value === 'conversation';
  return isTask || isConversation;
}

function FactsLine() {
  const people = TASK.assigneeIds.map(personOf);
  const firstNames = people.map((person) => person.firstName);
  const assigneeNames = firstNames.join(' and ');

  return (
    <dl className='mt-4 grid grid-cols-[6.5rem_minmax(0,1fr)] gap-x-3 gap-y-2.5 text-[13px]'>
      <dt className='text-muted-foreground'>Status</dt>
      <dd className='flex items-center gap-1.5'>
        <StatusGlyph status={TASK.status} />
        {STATUS_NAME[TASK.status]}
      </dd>
      <dt className='text-muted-foreground'>Assignees</dt>
      <dd className='flex min-w-0 items-center gap-2'>
        <PeopleStack people={people} />
        <span className='truncate'>{assigneeNames}</span>
      </dd>
      <dt className='text-muted-foreground'>Due</dt>
      <dd className='tabular-nums'>{dueLabelOf(TASK.due)}</dd>
    </dl>
  );
}

export default function TaskDetail04() {
  const [work, setWork] = useState<WorkState>(FIRST_STATE);
  const [typing, setTyping] = useState<Typing | null>(null);
  const [repliesUsed, setRepliesUsed] = useState(0);
  const [pane, setPane] = useState<Pane>('task');
  const timers = useRef(new Set<ReturnType<typeof setTimeout>>());
  const doneCount = doneCountOf(work.subtasks);
  const total = work.subtasks.length;
  const hidesTask = pane !== 'task';
  const hidesConversation = pane !== 'conversation';

  useEffect(() => {
    const pending = timers.current;
    return () => {
      pending.forEach((timer) => clearTimeout(timer));
    };
  }, []);

  function later(run: () => void, delay: number) {
    const timer = setTimeout(() => {
      timers.current.delete(timer);
      run();
    }, delay);
    timers.current.add(timer);
  }

  function answer(reply: TaskComment, replyIndex: number) {
    const typingId = `reply-${replyIndex}`;
    later(() => {
      setTyping({ id: typingId, authorId: reply.authorId });
      later(() => {
        const arrived: TaskComment = {
          ...reply,
          id: typingId,
          at: NOW,
          seq: nextSeq(),
        };
        setTyping(null);
        setWork((current) => withComment(current, arrived));
      }, TYPING_LASTS_MS);
    }, TYPING_STARTS_AFTER_MS);
  }

  function post(body: string) {
    setWork((current) => postedComment(current, body));
    const reply = LATER_REPLIES[repliesUsed];
    if (!reply) {
      return;
    }
    setRepliesUsed((current) => current + 1);
    answer(reply, repliesUsed);
  }

  function changePane(value: unknown) {
    if (isPane(value)) {
      setPane(value);
    }
  }

  return (
    <div className='bg-background text-foreground min-h-svh px-4 py-6 sm:px-8 lg:py-8'>
      <div className='mx-auto max-w-6xl'>
        <Tabs
          value={pane}
          onValueChange={changePane}
          className='mb-5 lg:hidden'
        >
          <TabsList variant='segmented' aria-label='Part of the task to show'>
            <TabsTab value='task'>Task</TabsTab>
            <TabsTab value='conversation'>
              Conversation
              <RollingCount
                value={work.comments.length}
                className='text-muted-foreground text-xs'
              />
            </TabsTab>
          </TabsList>
        </Tabs>
        <div className='grid gap-8 lg:grid-cols-[minmax(0,1fr)_24rem] lg:items-start'>
          <main className={cn('min-w-0', hidesTask && 'max-lg:hidden')}>
            <nav
              aria-label='Breadcrumb'
              className='text-muted-foreground flex items-center gap-1 text-xs'
            >
              <span>{TASK.project}</span>
              <ChevronRightIcon className='size-3' />
              <span className='tabular-nums'>{TASK.key}</span>
            </nav>
            <h1 className='mt-2 text-xl font-semibold text-balance sm:text-2xl'>
              {TASK.title}
            </h1>
            <FactsLine />
            <section aria-label='Description' className='mt-8'>
              <h2 className='text-sm font-medium'>Description</h2>
              <p className='mt-2 text-[13px] leading-relaxed'>
                {TASK.description}
              </p>
            </section>
            <section aria-label='Sub-tasks' className='mt-8'>
              <div className='flex items-center gap-2 px-2'>
                <h2 className='text-sm font-medium'>Sub-tasks</h2>
                <span className='text-muted-foreground flex items-center gap-1.5 text-xs font-medium'>
                  <ProgressRing done={doneCount} total={total} />
                  <span aria-hidden='true' className='flex tabular-nums'>
                    <RollingCount value={doneCount} />/
                    <RollingCount value={total} />
                  </span>
                  <span className='sr-only'>
                    {doneCount} of {total} done
                  </span>
                </span>
              </div>
              <div className='mt-2'>
                <SubtaskPanel
                  subtasks={work.subtasks}
                  onToggle={(subtaskId) =>
                    setWork((current) => toggledSubtask(current, subtaskId))
                  }
                  onAdd={(title) =>
                    setWork((current) => addedSubtask(current, title))
                  }
                />
              </div>
            </section>
          </main>
          <ConversationPane
            comments={work.comments}
            events={work.events}
            typing={typing}
            onPost={post}
            className={cn(
              'max-lg:min-h-[28rem] lg:sticky lg:top-8 lg:h-[calc(100svh-4rem)]',
              hidesConversation && 'max-lg:hidden'
            )}
          />
        </div>
      </div>
    </div>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useEffect, useRef } from 'react';

import { WordRoll } from '@/components/core/word-roll';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';

import { CommentComposer } from './comment-composer';
import { NOW, type TaskComment, type WorkEvent } from './data';
import { ENTER, EXIT, heightPresenceOf, RollingCount } from './motion-parts';
import { CommentText, EventGlyph, PersonAvatar } from './work-glyphs';
import { actorNameOf, clockOf, personOf, relativeTimeOf } from './work-model';

export type Typing = {
  id: string;
  authorId: string;
};

type CommentItem = {
  kind: 'comment';
  id: string;
  at: string;
  seq: number;
  comment: TaskComment;
  isTyping: boolean;
};

type EventItem = {
  kind: 'event';
  id: string;
  at: string;
  seq: number;
  event: WorkEvent;
};

type ConversationItem = CommentItem | EventItem;

const DOT_DELAYS = [0, 0.15, 0.3];

const FADE_PRESENCE = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

function commentItemOf(comment: TaskComment): ConversationItem {
  return {
    kind: 'comment',
    id: comment.id,
    at: comment.at,
    seq: comment.seq ?? 0,
    comment,
    isTyping: false,
  };
}

function eventItemOf(event: WorkEvent): ConversationItem {
  return {
    kind: 'event',
    id: event.id,
    at: event.at,
    seq: event.seq ?? 0,
    event,
  };
}

function typingItemOf(typing: Typing): ConversationItem {
  const placeholder: TaskComment = {
    id: typing.id,
    authorId: typing.authorId,
    at: NOW,
    body: '',
  };
  return {
    kind: 'comment',
    id: typing.id,
    at: NOW,
    seq: Number.MAX_SAFE_INTEGER,
    comment: placeholder,
    isTyping: true,
  };
}

function isShownEvent(event: WorkEvent) {
  return event.kind !== 'comment';
}

function byTimeThenOrder(first: ConversationItem, second: ConversationItem) {
  const byTime = first.at.localeCompare(second.at);
  if (byTime !== 0) {
    return byTime;
  }
  return first.seq - second.seq;
}

/** Comments and the changes made around them, in the order they happened. */
function itemsOf(
  comments: TaskComment[],
  events: WorkEvent[],
  typing: Typing | null
) {
  const commentItems = comments.map(commentItemOf);
  const shownEvents = events.filter(isShownEvent);
  const eventItems = shownEvents.map(eventItemOf);
  const items = [...commentItems, ...eventItems];
  if (typing) {
    items.push(typingItemOf(typing));
  }
  return items.sort(byTimeThenOrder);
}

function TypingDots() {
  const shouldReduceMotion = usePrefersReducedMotion();
  if (shouldReduceMotion) {
    return (
      <span aria-hidden='true' className='flex gap-1'>
        {DOT_DELAYS.map((delay) => (
          <span
            key={delay}
            className='bg-muted-foreground/60 size-1.5 rounded-full'
          />
        ))}
      </span>
    );
  }
  return (
    <span aria-hidden='true' className='flex gap-1'>
      {DOT_DELAYS.map((delay) => (
        <motion.span
          key={delay}
          animate={{ opacity: [0.25, 1, 0.25] }}
          transition={{
            duration: 1.2,
            delay,
            repeat: Infinity,
            ease: 'linear',
          }}
          className='bg-muted-foreground size-1.5 rounded-full'
        />
      ))}
    </span>
  );
}

function contentKeyOf(item: CommentItem) {
  if (item.isTyping) {
    return 'typing';
  }
  return 'comment';
}

/** One row that holds the typing state, then becomes the comment once it is sent. */
function CommentEntry({ item }: { item: CommentItem }) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const person = personOf(item.comment.authorId);

  return (
    <motion.li
      {...heightPresenceOf(shouldReduceMotion)}
      className='overflow-hidden'
    >
      <div className='flex gap-3 py-2'>
        <PersonAvatar person={person} className='size-7 text-[10px]' />
        <AnimatedSize className='min-w-0 flex-1'>
          <motion.div
            key={contentKeyOf(item)}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={ENTER}
          >
            {item.isTyping && (
              <p className='text-muted-foreground flex min-h-7 items-center gap-2 text-xs'>
                <TypingDots />
                {person.firstName} is typing
              </p>
            )}
            {!item.isTyping && (
              <>
                <p className='flex min-h-7 items-center gap-1.5 text-[13px]'>
                  <span className='truncate font-medium'>
                    {actorNameOf(item.comment.authorId)}
                  </span>
                  <span aria-hidden='true' className='text-muted-foreground'>
                    ·
                  </span>
                  <time
                    dateTime={item.at}
                    className='text-muted-foreground shrink-0 text-xs tabular-nums'
                  >
                    {relativeTimeOf(item.at)}
                  </time>
                </p>
                <CommentText body={item.comment.body} />
              </>
            )}
          </motion.div>
        </AnimatedSize>
      </div>
    </motion.li>
  );
}

function EventLine({ item }: { item: EventItem }) {
  return (
    <motion.li {...FADE_PRESENCE} className='flex gap-3 py-1.5 ps-0.5'>
      <EventGlyph kind={item.event.kind} className='size-6' />
      <p className='text-muted-foreground min-w-0 flex-1 pt-0.5 text-xs leading-5'>
        <span className='text-foreground font-medium'>
          {actorNameOf(item.event.actorId)}
        </span>{' '}
        {item.event.text}
        <time dateTime={item.at} className='ms-1.5 tabular-nums'>
          {clockOf(item.at)}
        </time>
      </p>
    </motion.li>
  );
}

function scrollBehaviorOf(shouldReduceMotion: boolean | null): ScrollBehavior {
  if (shouldReduceMotion) {
    return 'auto';
  }
  return 'smooth';
}

function commentWordOf(count: number) {
  if (count === 1) {
    return 'comment';
  }
  return 'comments';
}

type ConversationPaneProps = {
  comments: TaskComment[];
  events: WorkEvent[];
  typing: Typing | null;
  onPost: (body: string) => void;
  className?: string;
};

export function ConversationPane({
  comments,
  events,
  typing,
  onPost,
  className,
}: ConversationPaneProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const scrollRef = useRef<HTMLDivElement>(null);
  const hasScrolled = useRef(false);
  const items = itemsOf(comments, events, typing);
  const itemCount = items.length;
  const commentCount = comments.length;
  const commentWord = commentWordOf(commentCount);

  useEffect(() => {
    const area = scrollRef.current;
    if (!area) {
      return;
    }
    if (!hasScrolled.current) {
      hasScrolled.current = true;
      area.scrollTop = area.scrollHeight;
      return;
    }
    area.scrollTo({
      top: area.scrollHeight,
      behavior: scrollBehaviorOf(shouldReduceMotion),
    });
  }, [itemCount, shouldReduceMotion]);

  return (
    <aside
      aria-label='Conversation'
      className={cn(
        'bg-card hairline-ring ring-border flex min-h-0 flex-col rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
        className
      )}
    >
      <header className='flex items-baseline justify-between gap-3 px-4 pt-4'>
        <h2 className='text-sm font-medium'>Conversation</h2>
        <p className='text-muted-foreground text-xs'>
          <RollingCount value={commentCount} />{' '}
          <WordRoll text={commentWord} value={commentCount} />
        </p>
      </header>
      <div
        ref={scrollRef}
        className='min-h-0 flex-1 overflow-y-auto overscroll-contain px-4 py-2'
      >
        <ul aria-live='polite'>
          <AnimatePresence initial={false}>
            {items.map((item) => {
              if (item.kind === 'event') {
                return <EventLine key={item.id} item={item} />;
              }
              return <CommentEntry key={item.id} item={item} />;
            })}
          </AnimatePresence>
        </ul>
      </div>
      <CommentComposer
        onSubmit={onPost}
        placeholder='Write to the team'
        className='px-4 pt-2 pb-4'
      />
    </aside>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { PlusIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Checkbox } from '@/registry/ndeko/ui/checkbox';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { Subtask } from './data';
import { heightPresenceOf } from './motion-parts';
import { PersonAvatar, StrikeTitle } from './work-glyphs';
import { keyOf, personOf } from './work-model';

function SubtaskRow({
  subtask,
  onToggle,
}: {
  subtask: Subtask;
  onToggle: () => void;
}) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <motion.li
      {...heightPresenceOf(shouldReduceMotion)}
      className='overflow-hidden'
    >
      <label className='hover:bg-foreground/[0.03] flex h-9 cursor-pointer items-center gap-3 rounded-lg px-2'>
        <Checkbox checked={subtask.isDone} onCheckedChange={onToggle} />
        <span className='text-muted-foreground hidden w-16 shrink-0 text-xs tabular-nums sm:inline'>
          {keyOf(subtask.number)}
        </span>
        <StrikeTitle
          title={subtask.title}
          isDone={subtask.isDone}
          className='flex-1'
        />
        {subtask.assigneeId && (
          <PersonAvatar
            person={personOf(subtask.assigneeId)}
            className='size-5 text-[9px]'
          />
        )}
      </label>
    </motion.li>
  );
}

type SubtaskPanelProps = {
  subtasks: Subtask[];
  onToggle: (subtaskId: string) => void;
  onAdd: (title: string) => void;
};

export function SubtaskPanel({ subtasks, onToggle, onAdd }: SubtaskPanelProps) {
  const [title, setTitle] = useState('');
  const trimmed = title.trim();
  const canAdd = trimmed.length > 0;

  function add(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!canAdd) {
      return;
    }
    onAdd(trimmed);
    setTitle('');
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Escape') {
      setTitle('');
    }
  }

  return (
    <div className='flex flex-col gap-1'>
      <ul>
        <AnimatePresence initial={false}>
          {subtasks.map((subtask) => (
            <SubtaskRow
              key={subtask.id}
              subtask={subtask}
              onToggle={() => onToggle(subtask.id)}
            />
          ))}
        </AnimatePresence>
      </ul>
      <form
        onSubmit={add}
        className='hairline-border border-foreground/20 focus-within:border-foreground/35 flex h-9 items-center gap-3 rounded-lg border-dashed ps-2 pe-1.5 transition-colors'
      >
        <PlusIcon className='text-muted-foreground size-4 shrink-0' />
        <input
          value={title}
          onChange={(event) => setTitle(event.target.value)}
          onKeyDown={handleKeyDown}
          aria-label='New sub-task title'
          placeholder='Add a sub-task'
          className='placeholder:text-muted-foreground/75 h-8 min-w-0 flex-1 bg-transparent text-base outline-none md:text-[13px]'
        />
        <Kbd
          aria-hidden='true'
          className={cn(
            'transition-opacity duration-150',
            !canAdd && 'opacity-0'
          )}
        >
          Enter
        </Kbd>
        <button type='submit' className='sr-only'>
          Add sub-task
        </button>
      </form>
    </div>
  );
}

'use client';

import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Textarea } from '@/registry/ndeko/ui/textarea';

import { PersonAvatar } from './work-glyphs';
import { currentUser } from './work-model';

type CommentComposerProps = {
  onSubmit: (body: string) => void;
  placeholder?: string;
  className?: string;
};

function isSendKey(event: React.KeyboardEvent<HTMLTextAreaElement>) {
  const isCommand = event.metaKey || event.ctrlKey;
  return isCommand && event.key === 'Enter';
}

export function CommentComposer({
  onSubmit,
  placeholder = 'Leave a comment',
  className,
}: CommentComposerProps) {
  const [body, setBody] = useState('');
  const me = currentUser();
  const trimmed = body.trim();
  const canSend = trimmed.length > 0;

  function submit() {
    if (!canSend) {
      return;
    }
    onSubmit(trimmed);
    setBody('');
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    submit();
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (isSendKey(event)) {
      event.preventDefault();
      submit();
      return;
    }
    if (event.key === 'Escape') {
      event.stopPropagation();
      event.currentTarget.blur();
    }
  }

  return (
    <form
      onSubmit={handleSubmit}
      className={cn('flex items-start gap-3', className)}
    >
      <PersonAvatar person={me} className='mt-1 size-7 text-[10px]' />
      <div className='relative min-w-0 flex-1'>
        <Textarea
          value={body}
          onChange={(event) => setBody(event.target.value)}
          onKeyDown={handleKeyDown}
          rows={1}
          aria-label={`Comment as ${me.name}`}
          placeholder={placeholder}
          className='min-h-9 py-2 pe-24'
        />
        <Button
          type='submit'
          size='sm'
          disabled={!canSend}
          className='absolute end-1 bottom-1'
        >
          Comment
        </Button>
      </div>
    </form>
  );
}

import {
  CheckIcon,
  CircleDashedIcon,
  ClockIcon,
  ListTreeIcon,
  MessageCircleIcon,
  PlusIcon,
  UserIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import type { Person, StatusId, WorkEventKind } from './data';
import { segmentsOf } from './work-model';

const STATUS_COLOR: Record<StatusId, string> = {
  backlog: 'var(--muted-foreground)',
  todo: 'var(--muted-foreground)',
  in_progress: 'var(--warning)',
  in_review: 'var(--primary)',
  done: 'var(--success)',
};

export const STATUS_NAME: Record<StatusId, string> = {
  backlog: 'Backlog',
  todo: 'Todo',
  in_progress: 'In progress',
  in_review: 'In review',
  done: 'Done',
};

const PIE_RADIUS = 2;

const PIE_CIRCUMFERENCE = 2 * Math.PI * PIE_RADIUS;

function StartedShape({ share }: { share: number }) {
  const filled = share * PIE_CIRCUMFERENCE;
  return (
    <>
      <circle cx='7' cy='7' r='6' stroke='currentColor' strokeWidth='1.5' />
      <circle
        cx='7'
        cy='7'
        r={PIE_RADIUS}
        stroke='currentColor'
        strokeWidth={PIE_RADIUS * 2}
        strokeDasharray={`${filled} ${PIE_CIRCUMFERENCE}`}
        transform='rotate(-90 7 7)'
      />
    </>
  );
}

function statusShapeOf(status: StatusId) {
  if (status === 'backlog') {
    return (
      <circle
        cx='7'
        cy='7'
        r='6'
        stroke='currentColor'
        strokeWidth='1.5'
        strokeDasharray='1.6 1.9'
      />
    );
  }
  if (status === 'todo') {
    return (
      <circle cx='7' cy='7' r='6' stroke='currentColor' strokeWidth='1.5' />
    );
  }
  if (status === 'in_progress') {
    return <StartedShape share={0.5} />;
  }
  if (status === 'in_review') {
    return <StartedShape share={0.75} />;
  }
  return (
    <>
      <circle cx='7' cy='7' r='7' fill='currentColor' />
      <path
        d='M4.4 7.2 6.2 9l3.4-3.8'
        stroke='var(--card)'
        strokeWidth='1.6'
        strokeLinecap='round'
        strokeLinejoin='round'
      />
    </>
  );
}

export function StatusGlyph({
  status,
  className,
}: {
  status: StatusId;
  className?: string;
}) {
  const glyphStyle = { color: STATUS_COLOR[status] } as React.CSSProperties;
  return (
    <svg
      viewBox='0 0 14 14'
      fill='none'
      aria-hidden='true'
      style={glyphStyle}
      className={cn('size-3.5 shrink-0', className)}
